  Item_125189_Name = {
    Text = "Caramella allo sciroppo di pera"
  },
  Item_125190_Desc = {
    Text = "Dopo aver registrato questo Posse, puoi selezionare l'Abilità di posse: \"Echi del Maniero\".\nIl maniero isolato custodisce troppi segreti — di potere, di ossessione, di desiderio.\nDello sguardo che la divinità maligna posa sul mondo mortale, colmo di un amore tanto \"estasiato\" quanto \"distorto.\""
  },
  Item_125190_Name = {
    Text = "Echi del maniero"
  },
