  Item_130224_Desc = {
    Text = "La coscienza perduta di un'antica volontà. Mythag illumina la coscienza dei Risvegliati attraverso un misterioso rito, e il Risvegliato Illuminato otterrà potenziamenti permanenti.\nConvertito all'ottenimento di un duplicato di Shaya. Attiva le Illuminazioni di Saya."
  },
  Item_130224_Name = {
    Text = "Frammento: Saya"
  },
  Item_130224_StoryDesc = {
    Text = "Convertito all'ottenimento di un duplicato di Saya. Attiva le Illuminazioni di Saya."
  },
  Item_130225_Name = {Text = "Shaye"},
  Item_130363_Desc = {
    Text = "Si sblocca dopo aver ottenuto il Risveglio \"Tsathoggua\""
  },
  Item_130363_Name = {Text = "Tsathoggua"},
