  Item_50032_Name = {Text = "Mandibola"},
  Item_51105_Desc = {
    Text = "Nell'evento \"La Magia delle Storie: Replica\", questo oggetto si ottiene completando il \"Mistero Ordito\" o raggiungendo gli obiettivi dell'evento. Può essere utilizzato per lo scambio nell'\"Emporio del Codice Arcano\".\nL'Ispirazione è fugace, come una meteora che solca il cielo notturno. La differenza è che tu hai un modo per preservarla per sempre."
  },
  Item_51105_Name = {
    Text = "Ispirazione alla Deriva"
  },
